/**
 * Dance loops for the crater dancer, converted from motion capture.
 *
 * Source: CMU Graphics Lab Motion Capture Database, http://mocap.cs.cmu.edu/
 * "The data used in this project was obtained from mocap.cs.cmu.edu. The
 * database was created with funding from NSF EIA-0196217." The data is free
 * to use, including in products, but may not be resold on its own.
 *
 * Each take was read from its ASF/AMC files, turned to face the camera
 * (slowly smoothed heading), had its travel across the floor removed, was
 * projected to a front view and scaled to a figure about 1 unit tall with
 * the ground at y = 0 (y up). Its own pulse was estimated from the body's
 * bounce; the most energetic 8 beats were resampled to SAMPLES_PER_BEAT
 * samples per beat, with the last beat blended into the first so it loops.
 * The head joint is the centre of the head.
 *
 * Generated by a conversion script; do not edit by hand.
 */

export const DANCE_JOINTS = ["pelvis", "neck", "head", "shoulderL", "shoulderR", "elbowL", "elbowR", "handL", "handR", "hipL", "hipR", "kneeL", "kneeR", "footL", "footR"] as const
export type DanceJoint = (typeof DANCE_JOINTS)[number]
export const BEATS_PER_LOOP = 8
export const SAMPLES_PER_BEAT = 12

export interface DanceClip {
  name: string
  /** Which take it came from. */
  source: string
  /** Flattened frames: BEATS_PER_LOOP × SAMPLES_PER_BEAT frames of [x, y] per joint, in DANCE_JOINTS order. */
  frames: number[]
}

